def collapse_whitespace(s: str) -> str:
    """Collapse runs of ASCII whitespace into one space and strip leading/trailing."""
    result = []
    prev_was_space = False
    for ch in s:
        if ch in " \t\r\n\x0b\x0c":
            if not prev_was_space:
                result.append(' ')
                prev_was_space = True
        else:
            result.append(ch)
            prev_was_space = False
    # strip leading/trailing spaces only
    while result and result[0] == ' ':
        result.pop(0)
    while result and result[-1] == ' ':
        result.pop()
    return ''.join(result)
